BEGIN;
CREATE TABLE IF NOT EXISTS ticket_archive_rules (id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,is_enabled BOOLEAN NOT NULL DEFAULT FALSE,trigger_type VARCHAR(60) NOT NULL DEFAULT 'requester_non_response',wait_days INTEGER NOT NULL DEFAULT 14,reminder_days INTEGER[] NOT NULL DEFAULT ARRAY[7,12],final_warning_days INTEGER NOT NULL DEFAULT 13,excluded_priorities TEXT[] NOT NULL DEFAULT ARRAY['Critical'],exclude_escalated BOOLEAN NOT NULL DEFAULT TRUE,exclude_waiting_approval BOOLEAN NOT NULL DEFAULT TRUE,created_by_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,updated_by_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,change_reason TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT NOW(),updated_at TIMESTAMP NOT NULL DEFAULT NOW(),last_evaluated_at TIMESTAMP,last_execution_count INTEGER NOT NULL DEFAULT 0,CHECK(wait_days BETWEEN 1 AND 365),CHECK(final_warning_days BETWEEN 0 AND 364));
CREATE INDEX IF NOT EXISTS idx_ticket_archive_rules_enabled ON ticket_archive_rules(is_enabled,trigger_type);
COMMIT;
